"""Publish the illustrated production roster alongside its Sol references."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
GAME=ROOT/'html-games/broken-mirror-port'
plan=json.loads((ROOT/'tools/system-completion.json').read_text(encoding='utf-8'))
for s in plan['systems']:
    s['released']=s['id'] in plan['releasedSystems']
    for p in s['planets']:
        p['ready']=all((GAME/'assets/system-planets'/(p['asset']+ext)).is_file() for ext in ['.webp','.provenance.json'])
data=json.dumps(plan,ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vexed Mirror · Planet artwork</title>
<style>*{box-sizing:border-box}body{margin:0;background:#060a12;color:#dfe7ef;font:16px/1.6 system-ui}main{max-width:1500px;margin:auto;padding:40px 28px}h1{font-weight:500;font-size:36px;margin:0}p{max-width:850px;color:#a9b8c8}a{color:#8ed6e8}nav{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:30px}.refs,.worlds{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px}.refs{max-width:1000px}.worlds{grid-template-columns:repeat(auto-fill,minmax(245px,1fr))}article{background:#0b1320;border:1px solid #243248;padding:18px;border-radius:12px}img{width:100%;aspect-ratio:1;object-fit:contain;display:block;background:#000;border-radius:8px}h2{margin:38px 0 8px;font-weight:500}h3{margin:12px 0 4px;font-size:19px}article p{font-size:14px;margin:6px 0}.status{font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#9bb0c7}.ready{color:#96d9b5}.queue{background:#101b2b;min-height:210px;display:grid;place-items:center;color:#8595a8;border-radius:8px}label{display:block;margin:28px 0}select{padding:10px;background:#122033;color:#dfe7ef;border:1px solid #415772;border-radius:6px;font:inherit}button{padding:10px 16px;margin-left:12px;background:#122033;color:#dfe7ef;border:1px solid #415772;border-radius:6px;cursor:pointer}@media(max-width:600px){main{padding:24px 16px}.refs{grid-template-columns:repeat(3,1fr)}.refs article{padding:8px}.refs h3{font-size:13px}.worlds{grid-template-columns:1fr 1fr;gap:10px}.worlds article{padding:10px}h1{font-size:27px}}</style>
<main><nav><a href="index.html">Open game</a><a href="system-atlas.html">System atlas</a></nav><h1>Worlds of Vexed Mirror</h1><p>Earth and the planets of Sol set the visual standard. Each new world follows the approved appearance catalogue, with its own generated artwork.</p><p id="progress"></p><div class="refs"><article><img src="../flashtrek-broken-mirror/art-review/sol-planets/03 - Earth.png" alt="Sol Earth reference"><h3>Earth · reference</h3></article><article><img src="../flashtrek-broken-mirror/art-review/sol-planets/05 - Mars.png" alt="Sol Mars reference"><h3>Mars · reference</h3></article><article><img src="../flashtrek-broken-mirror/art-review/sol-planets/08 - Saturn.png" alt="Sol Saturn reference"><h3>Saturn · reference</h3></article></div><label>System <select id="system"><option value="ready">Illustrated systems</option><option value="all">All 40 planned systems</option></select></label><div id="catalogue"></div><p>New companion names, landscapes and orbital layouts are game adaptations. The remaining 28 moon specifications await the detailed catalogue; existing moons stay in place.</p></main><script>
const plan=__PLAN__,select=document.getElementById('system'),host=document.getElementById('catalogue');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const total=plan.systems.flatMap(s=>s.planets),ready=total.filter(p=>p.ready).length;
document.getElementById('progress').textContent=`${ready} of 215 planet images illustrated · ${plan.releasedSystems.length} of 40 systems implemented`;
for(const s of plan.systems)select.add(new Option(s.name,String(s.id)));
function render(){const systems=plan.systems.filter(s=>select.value==='all'||select.value==='ready'&&s.planets.some(p=>p.ready)||Number(select.value)===s.id);host.innerHTML=systems.map(s=>`<section><h2>${safe(s.name)}</h2><p class="status ${s.released?'ready':''}">${s.planets.length} planets · ${s.released?'Implemented in game':'In preparation'}</p><div class="worlds">${s.planets.map(p=>`<article>${p.ready?`<a href="assets/system-planets/${p.asset}.webp"><img loading="lazy" src="assets/system-planets/${p.asset}.webp" alt="${safe(p.name)}"></a>`:'<div class="queue">Artwork pending</div>'}<h3>${safe(p.name)}</h3><p class="status">${p.kind.replaceAll('_',' ')} · ${s.id===4?'Star '+(p.starId===900?'A':'B')+' · ':''}Orbit ${p.orbitOrder}</p><p>${safe(p.appearance)}</p></article>`).join('')}</div></section>`).join('');}
select.onchange=render;render();</script></html>'''.replace('__PLAN__',data)
(GAME/'system-completion-preview.html').write_text(html,encoding='utf-8')
print(json.dumps(dict(illustrated=sum(p['ready'] for s in plan['systems'] for p in s['planets']),planned=215,released=plan['releasedSystems'])))
